//! `GET /catalog.json`, generated by the host: `{"format":1,"regions":[...]}`.
//!
//! Pre-extracted mode lists the manifest (`<stem>.json`) of every allow-listed region in the
//! directory. Cache mode lists every allow-listed region of the region list: its manifest if
//! it has been cut, otherwise `{"id","name","group","status":"on_demand"}`. Regions are sorted
//! by id. A manifest that is not a JSON object is left out.

use std::io;

use serde_json::{Map, Value};

use crate::cache::Cache;
use crate::files::Directory;
use crate::region::{AllowList, FileKind, RegionFile, RegionId};

/// The catalog format number.
pub const FORMAT: u32 = 1;

/// Builds the catalog body. Blocking.
///
/// # Errors
///
/// If the directory cannot be listed or JSON cannot be written.
pub fn build(
    directory: &Directory,
    allow: &AllowList,
    cache: Option<&Cache>,
) -> io::Result<Vec<u8>> {
    let mut regions: Vec<(RegionId, Value)> = Vec::new();
    match cache {
        None => {
            for (file, _) in directory.region_files()? {
                if file.kind == FileKind::Manifest
                    && allow.allows(&file.region)
                    && let Some(manifest) = read_manifest(directory, &file)
                {
                    regions.push((file.region, manifest));
                }
            }
        }
        Some(cache) => {
            for entry in cache.regions() {
                let file = RegionFile {
                    region: entry.id.clone(),
                    kind: FileKind::Manifest,
                };
                let manifest = if cache.is_preparing(&entry.id) {
                    None
                } else {
                    read_manifest(directory, &file)
                };
                let value = manifest.unwrap_or_else(|| {
                    let mut stub = Map::new();
                    stub.insert("id".to_owned(), Value::from(entry.id.as_str()));
                    stub.insert("name".to_owned(), Value::from(entry.name.as_str()));
                    if let Some(group) = &entry.group {
                        stub.insert("group".to_owned(), Value::from(group.as_str()));
                    }
                    stub.insert("status".to_owned(), Value::from("on_demand"));
                    Value::Object(stub)
                });
                regions.push((entry.id.clone(), value));
            }
        }
    }
    regions.sort_by(|left, right| left.0.cmp(&right.0));
    let mut catalog = Map::new();
    catalog.insert("format".to_owned(), Value::from(FORMAT));
    catalog.insert(
        "regions".to_owned(),
        Value::Array(regions.into_iter().map(|(_, value)| value).collect()),
    );
    serde_json::to_vec(&Value::Object(catalog)).map_err(io::Error::other)
}

fn read_manifest(directory: &Directory, file: &RegionFile) -> Option<Value> {
    let bytes = std::fs::read(directory.root().join(file.name())).ok()?;
    serde_json::from_slice::<Value>(&bytes)
        .ok()
        .filter(Value::is_object)
}
